import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"西湖掠影","description":"","frontmatter":{"title":"西湖掠影","date":"2025-09-24T00:00:00.000Z","category":"随笔","tags":["游记"]},"headers":[],"relativePath":"articles/notes/journal/xihu.md","filePath":"articles/notes/journal/xihu.md","articleMeta":{"updated":"2025-09-24","words":371,"minutes":1}}`),a={name:`articles/notes/journal/xihu.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>又是一年出差季，区域回访的工作愈发形式主义、走马观花。往返路途耽误自己本职工作的时间，分行接待也是“煞费苦心”。就好像逢场作戏，顺着剧本走完。</p><p>抵达杭州的夜晚，顺着西湖走一走，赶上了音乐喷泉与人山人海。iPhone 17 发售的前夜，APPLE STORE也是人山人海。杭州西湖真的是很有活力的城区，各色人群中又多为年轻的面孔，散发着朝气蓬勃。</p><p><img src="/images/IMG_4638.jpg" alt="IMG_4638.jpg" width="5712" height="3213"></p><p><img src="/images/IMG_4668.jpeg" alt="IMG_4668.jpeg" width="4032" height="3024"></p><p><img src="/images/IMG_4665.jpeg" alt="IMG_4665.jpeg" width="4032" height="3024"></p><p><img src="/images/IMG_4657.jpeg" alt="IMG_4657.jpeg" width="4032" height="3024"></p><p><img src="/images/IMG_4643-Ormb.jpeg" alt="IMG_4643-Ormb.jpeg" width="5712" height="3213"></p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};